<?php
namespace App\Repositories; use App\Enums\UserRole; use App\Models\{Order, User}; use Illuminate\Contracts\Pagination\LengthAwarePaginator; use Illuminate\Database\Eloquent\Collection;
class OrderRepository { public function paginateFor(User $user, int $perPage = 15): LengthAwarePaginator { return Order::query()->with(['customer','worker'])->when($user->role === UserRole::Customer, fn($q)=>$q->where('customer_id',$user->id))->when($user->role === UserRole::Worker, fn($q)=>$q->where('worker_id',$user->id))->latest()->paginate($perPage); } public function delayed(): Collection { return Order::query()->whereNotIn('status',['COMPLETED','CANCELLED'])->where('deadline','<',now())->get(); } public function create(array $attributes): Order { return Order::create($attributes); } }
